<?php use App\Core\Csrf; ?>
<h1>Hours approval</h1>
<form class="card filters" method="get"><div><label for="st">Status</label><select id="st" name="status"><?php foreach (['pending','approved','revision_requested','rejected','voided'] as $s): ?><option value="<?= $s ?>"<?= $f['status'] === $s ? ' selected' : '' ?>><?= e(label($s)) ?></option><?php endforeach; ?></select></div>
<div><label for="pj">Project</label><select id="pj" name="project"><option value="">All my projects</option><?php foreach ($projects as $p): ?><option value="<?= (int) $p['id'] ?>"<?= $f['project'] === (string) $p['id'] ? ' selected' : '' ?>><?= e($p['name']) ?></option><?php endforeach; ?></select></div><div><button class="btn">Show</button></div></form>
<div class="card table-wrap"><?php if (!$rows): ?><p class="empty">Nothing to review.</p><?php else: ?><table><thead><tr><th>Volunteer</th><th>Date</th><th>Project</th><th>For</th><th>Hours</th><th>Description</th><th>Decision</th></tr></thead><tbody>
<?php foreach ($rows as $t): ?><tr><td><?= e($t['full_name']) ?></td><td><?= e(fmt_date($t['work_date'])) ?></td><td><?= e($t['project_name']) ?></td><td><?= e($t['activity_title'] ?? $t['task_title'] ?? 'General work') ?><?= $t['resubmission_of_id'] ? '<br><span class="badge warn">Resubmission</span>' : '' ?></td>
<td><?= e(minutes_to_hours($t['minutes'])) ?></td><td><?= e($t['description']) ?></td><td>
<?php if ($t['status'] === 'pending' && (int) $t['submitted_by'] !== App\Security\Auth::id()): ?><form method="post" action="<?= e(url('/hours/' . $t['id'] . '/review')) ?>"><?= Csrf::field() ?><input type="hidden" name="back" value="pending">
<input name="comment" maxlength="500" placeholder="Comment (required unless approving)" aria-label="Comment"><div class="actions"><button class="btn small" name="decision" value="approve">Approve</button><button class="btn small secondary" name="decision" value="revision">Request revision</button><button class="btn small danger" name="decision" value="reject">Reject</button></div></form>
<?php elseif ($t['status'] === 'approved'): ?><details><summary>Void</summary><form method="post" action="<?= e(url('/hours/' . $t['id'] . '/review')) ?>"><?= Csrf::field() ?><input type="hidden" name="back" value="approved"><input name="comment" required maxlength="255" placeholder="Reason" aria-label="Void reason"><button class="btn small danger" name="decision" value="void">Void hours</button></form></details>
<?php else: ?><?= e(label($t['status'])) ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
